package com.delivery.platform.catalog.pricing.api;
import com.delivery.platform.catalog.common.CatalogSupport;import com.delivery.platform.common.ApiException;import com.delivery.platform.identity.security.IdentityPrincipal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*;
@RestController public class PricingController {private final JdbcClient db;private final CatalogSupport support;public PricingController(JdbcClient d,CatalogSupport s){db=d;support=s;}public record PriceList(UUID id,UUID merchantId,String name,String code,String currency,boolean active,Instant validFrom,Instant validTo){}public record Save(@NotBlank String name,@NotBlank String code,@Pattern(regexp="[A-Z]{3}")String currency,boolean active,Instant validFrom,Instant validTo){}public record Item(UUID id,UUID productId,UUID variantId,BigDecimal price){}public record SaveItem(UUID productId,UUID variantId,@NotNull @DecimalMin("0")BigDecimal price){}public record Items(@NotNull List<SaveItem> items){}
 @GetMapping("/api/v1/merchants/{merchantId}/price-lists") @PreAuthorize("hasAuthority('CATALOG_PRICING_VIEW')") public List<PriceList> list(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID merchantId){support.merchant(p,merchantId);return db.sql("select * from price_lists where tenant_id=:t and merchant_id=:m order by name").param("t",p.tenantId()).param("m",merchantId).query(PriceList.class).list();}
 @PostMapping("/api/v1/merchants/{merchantId}/price-lists") @Transactional @PreAuthorize("hasAuthority('CATALOG_PRICING_MANAGE')") public PriceList create(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID merchantId,@Valid @RequestBody Save q){support.merchant(p,merchantId);validate(q);UUID id=UUID.randomUUID();db.sql("insert into price_lists(id,tenant_id,merchant_id,name,code,currency,active,valid_from,valid_to) values(:i,:t,:m,:n,lower(:c),:u,:a,:f,:x)").param("i",id).param("t",p.tenantId()).param("m",merchantId).param("n",q.name()).param("c",q.code()).param("u",q.currency()).param("a",q.active()).param("f",q.validFrom()==null?null:OffsetDateTime.ofInstant(q.validFrom(),ZoneOffset.UTC)).param("x",q.validTo()==null?null:OffsetDateTime.ofInstant(q.validTo(),ZoneOffset.UTC)).update();support.audit(p,"PRICE_LIST_CREATED","PRICE_LIST",id);return one(p,id);}
 @GetMapping("/api/v1/price-lists/{id}") @PreAuthorize("hasAuthority('CATALOG_PRICING_VIEW')") public PriceList one(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id){return db.sql("select * from price_lists where id=:i and tenant_id=:t").param("i",id).param("t",p.tenantId()).query(PriceList.class).optional().orElseThrow(this::missing);}
 @PutMapping("/api/v1/price-lists/{id}") @Transactional @PreAuthorize("hasAuthority('CATALOG_PRICING_MANAGE')") public PriceList update(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id,@Valid @RequestBody Save q){one(p,id);validate(q);db.sql("update price_lists set name=:n,code=lower(:c),currency=:u,active=:a,valid_from=:f,valid_to=:x,updated_at=now() where id=:i").param("n",q.name()).param("c",q.code()).param("u",q.currency()).param("a",q.active()).param("f",q.validFrom()==null?null:OffsetDateTime.ofInstant(q.validFrom(),ZoneOffset.UTC)).param("x",q.validTo()==null?null:OffsetDateTime.ofInstant(q.validTo(),ZoneOffset.UTC)).param("i",id).update();support.audit(p,"PRICE_LIST_UPDATED","PRICE_LIST",id);return one(p,id);}
 @DeleteMapping("/api/v1/price-lists/{id}") @Transactional @PreAuthorize("hasAuthority('CATALOG_PRICING_MANAGE')") public void delete(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id){one(p,id);db.sql("update price_lists set active=false,updated_at=now() where id=:i").param("i",id).update();support.audit(p,"PRICE_LIST_DELETED","PRICE_LIST",id);}
 @GetMapping("/api/v1/price-lists/{id}/items") @PreAuthorize("hasAuthority('CATALOG_PRICING_VIEW')") public List<Item> items(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id){one(p,id);return db.sql("select id,product_id,variant_id,price from price_list_items where price_list_id=:i order by created_at").param("i",id).query(Item.class).list();}
 @PutMapping("/api/v1/price-lists/{id}/items") @Transactional @PreAuthorize("hasAuthority('CATALOG_PRICING_MANAGE')") public List<Item> replace(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id,@Valid @RequestBody Items q){PriceList list=one(p,id);db.sql("delete from price_list_items where price_list_id=:i").param("i",id).update();for(SaveItem x:q.items()){if((x.productId()==null)==(x.variantId()==null))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_PRICE_ITEM","Indica exactamente un producto o variante");UUID merchant=x.productId()!=null?db.sql("select merchant_id from products where id=:i and tenant_id=:t").param("i",x.productId()).param("t",p.tenantId()).query(UUID.class).optional().orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"INVALID_PRICE_ITEM","Producto no válido")):db.sql("select p.merchant_id from product_variants v join products p on p.id=v.product_id where v.id=:i and v.tenant_id=:t").param("i",x.variantId()).param("t",p.tenantId()).query(UUID.class).optional().orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"INVALID_PRICE_ITEM","Variante no válida"));if(!merchant.equals(list.merchantId()))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_PRICE_ITEM","El elemento debe pertenecer al mismo comercio");db.sql("insert into price_list_items(tenant_id,price_list_id,product_id,variant_id,price) values(:t,:l,:p,:v,:x)").param("t",p.tenantId()).param("l",id).param("p",x.productId()).param("v",x.variantId()).param("x",x.price()).update();}support.audit(p,"PRICE_LIST_UPDATED","PRICE_LIST",id);return items(p,id);}
 private void validate(Save q){if(q.validFrom()!=null&&q.validTo()!=null&&!q.validTo().isAfter(q.validFrom()))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_PRICE_LIST","La fecha final debe ser posterior a la inicial");}private ApiException missing(){return new ApiException(HttpStatus.NOT_FOUND,"PRICE_LIST_NOT_FOUND","Lista de precios no encontrada");}}
